[
  {
    "id": "90000000-0000-0000-0000-000000000379",
    "title": "Evangelists of Art: Picture-Sermons for Children",
    "description": "The public-domain text of Evangelists of Art: Picture-Sermons for Children by James Patrick, preserved across 1 original section with extracted Scripture references.",
    "total_days": 11,
    "tags": [
      "knowledge",
